const icons={"t":"data:image/jpeg;base64,","alfa":"data:image/png;base64,","sber":"data:image/png;base64,","ozon":"data:image/png;base64,","vtb":"data:image/png;base64,"};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const banks=[[/^(Т[-‑– ]Банк|Тинькофф|Tinkoff)(?=\s|$)/i,'t'],[/^(Альфа[-‑– ]Банк)(?=\s|$)/i,'alfa'],[/^(ВТБ)(?=\s|$)/i,'vtb'],[/^(Сбер(?:банк)?)(?=\s|$)/i,'sber'],[/^(OZON(?: Банк)?)(?=\s|$)/i,'ozon'],[/^(Лояльность МИР)(?=\s|$)/i,'mir']];
export function bankHeader(label,category=''){
 if(label==='Наличные')return `<span class="bank-heading"><svg class="bank-logo bank-symbol cash-stack-icon" aria-hidden="true" width="32" height="32" viewBox="0 0 32 32"><g fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"><path d="m3 17 13 7 13-7M3 22l13 7 13-7"/><path d="M3 12 16 5l13 7-13 7z" fill="#edf3e8"/><path d="m11 8 13 7m-16-1 13-7"/><ellipse cx="16" cy="12" rx="3" ry="1.7" fill="#c5d5b3"/></g></svg><span class="bank-name">Наличные</span></span>`;
 let name=label,detail='',icon='';for(const [pattern,key]of banks){const match=label.match(pattern);if(match){name=match[1];detail=label.slice(match[0].length).replace(/^\s*[·—–-]?\s*/,'');icon=icons[key]||'';break;}}
 if(/^СберСпасибо$/i.test(label))icon=icons.sber;if(/^МИР$/i.test(label))icon=icons.nspk;if(/^WB$/i.test(label))icon=icons.wb;if(/^LB$/i.test(label))icon=icons.lb;
 const logo=icon?`<img class="bank-logo" src="${icon}" alt="" width="32" height="32">`:`<svg class="bank-logo bank-symbol" aria-hidden="true" width="32" height="32" viewBox="0 0 28 28"><path d="M3 10 14 4l11 6M4 12h20M6 12v10m8-10v10m8-10v10M3 24h22" fill="none" stroke="currentColor" stroke-width="1.5"/></svg>`;
 return `<span class="bank-heading">${logo}<span class="bank-name">${esc(name)}</span>${detail?`<span class="bank-detail">${esc(detail)}</span>`:''}${category?`<small class="bank-category">${esc(category)}</small>`:''}</span>`;
}

icons["gazprom"]="data:image/png;base64,";

icons["yandex"]="data:image/x-icon;base64,";

export function bankLogo(key){return icons[key]?`<img class="bank-logo" src="${icons[key]}" alt="" width="32" height="32">`:`<span class="cashback-generic-logo" aria-hidden="true">₽</span>`;}

export function accountBank(name){if(/(?:^|[\s·—–-])Наличные\s*$/i.test(String(name||'')))return 'Наличные';const m=String(name||'').match(/^(Сбер(?:банк)?|Т[-‑– ]Банк|Альфа[-‑– ]Банк|OZON(?: Банк)?|ВТБ|Газпромбанк|Яндекс(?: Банк)?|LB|WB)/i);return m?m[1]:'Другие счета';}

icons["wb"]="data:image/png;base64,";

icons["nspk"]="data:image/png;base64,";

icons.lb="data:image/png;base64,";

export function accountBankKey(name){return accountBank(name).toLocaleLowerCase().replace(/[\s\u2011\u2013-]/g,'').replace(/^\u0441\u0431\u0435\u0440\u0431\u0430\u043d\u043a$/,'\u0441\u0431\u0435\u0440').replace(/^ozon\u0431\u0430\u043d\u043a$/,'ozon');}
